+
+    public Task<List<Shipment>> GetMyShipmentsAsync()
+    {
+        var userEmail = httpContextAccessor.HttpContext?.User?.Identity?.Name ?? string.Empty;
+        var result = SeedShipments.Where(s =>
+            s.CustomerEmail.Equals(userEmail, StringComparison.OrdinalIgnoreCase)).ToList();
+        return Task.FromResult(result);
+    }
