using System.Security.Claims;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", (IShipmentService service, ShipmentStatus? status) =>
            service.GetShipmentsByStatusAsync(status));

        group.MapGet("/track/{trackingNumber}", async (IShipmentService service, string trackingNumber) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/mine", (IShipmentService service) =>
            service.GetMyShipmentsAsync());

        group.MapPut("/{id}/status", async (IShipmentService service, int id, ShipmentStatus status) =>
        {
            await service.UpdateShipmentStatusAsync(id, status);
            return Results.NoContent();
        }).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));
    }
}

